// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ComputeImage) predicate.ComputeImage {
	return predicate.ComputeImage(func(s *sql.Selector) {
		s1 := s.Clone().SetP(nil)
		for _, p := range predicates {
			p(s1)
		}
		s.Where(s1.P())
	})
}

